(function(root){
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(target,ctx,data={}){
 const {t,count}=ctx,button=(id,label,primary=false)=>'<button type="button" id="svc-'+id+'" class="button button-'+(primary?'primary':'outline')+'">'+label+'</button>';
 const rows=data.rows||[],totals=data.totals;
 const summaries=[['total',t('إجمالي الطلبات','Total requests'),''],['draft',t('المسودات','Drafts'),'draft'],['in_review',t('قيد المراجعة','In review'),'in_review'],['active',t('المناصب المعتمدة','Approved positions'),'active']];
 target.innerHTML='<section class="svc-start"><div><span class="svc-kicker">'+esc(ctx.authenticated?ctx.organization:t('مساحة هذا الجهاز','This device’s workspace'))+'</span><h2>'+t(ctx.authenticated?'ماذا تريد أن تنجز اليوم؟':'ابدأ طلب منصبك.',ctx.authenticated?'What would you like to work on?':'Start your position request.')+'</h2><p>'+t('أنشئ الطلب، حدّد مهامه ومتطلباته، ثم جهّز الوصف الوظيفي للمراجعة والاعتماد.','Create a request, define responsibilities and requirements, then prepare the job description for review and approval.')+'</p></div><div class="action-row">'+(ctx.canCreate?button('new',t('إنشاء منصب','Create position'),true):button('reviews',t('فتح طلبات المراجعة','Open requests for review'),true))+button('register',t('جميع الطلبات','All requests'))+'</div></section>'+
 (!ctx.authenticated?'<aside class="svc-storage"><div><strong>'+t('المسودات محفوظة على هذا الجهاز','Drafts are saved on this device')+'</strong><p>'+t('يمكنك العمل الآن وتنزيل نسخة احتياطية. سجّل الدخول بحساب المؤسسة للحفظ المشترك والاعتمادات.','Work now and download a backup. Sign in with your organization account for shared storage and approvals.')+'</p></div>'+button('account',t('دخول المؤسسة','Organization sign in'))+'</aside>':'')+
 (ctx.draft?'<section class="svc-resume"><div><strong>'+t('تابع عملك الحالي','Continue your current work')+'</strong><p dir="auto">'+esc(ctx.draft.title||t('طلب غير مسمّى','Untitled request'))+' · '+t(ctx.draft.dirty?'توجد تعديلات غير محفوظة':'مسودة مفتوحة',ctx.draft.dirty?'Unsaved changes':'Open draft')+'</p></div>'+button('resume',t('متابعة المسودة','Continue draft'),true)+'</section>':'')+
 (ctx.needsSetup?'<section class="svc-storage"><div><strong>'+t('أكمل إعداد المؤسسة','Complete organization setup')+'</strong><p>'+t('أضف إدارة وحسابات المراجعين لتبدأ دورة الاعتماد.','Add a department and reviewer accounts to begin the approval workflow.')+'</p></div>'+button('setup',t('إعداد المؤسسة','Set up organization'))+'</section>':'')+
 '<div class="svc-metrics">'+summaries.map(([key,label,state])=>'<button type="button" data-svc-state="'+state+'"><span>'+label+'</span><strong>'+(totals?count(totals[key]||0):'—')+'</strong></button>').join('')+'</div>'+
 '<section class="ent-card svc-register"><div class="svc-section-head"><div><h2>'+t('آخر الطلبات','Recent requests')+'</h2><p>'+t(ctx.authenticated?'الطلبات التي تسمح صلاحية حسابك بالوصول إليها.':'المسودات التي حفظتها في هذا المتصفح.',ctx.authenticated?'Requests accessible under your account permissions.':'Drafts saved in this browser.')+'</p></div>'+button('refresh',t('تحديث','Refresh'))+'</div><div id="svc-load-status" role="status">'+(data.loading?t('جارٍ تحميل الطلبات…','Loading requests…'):data.failed?t('تعذر تحميل الطلبات. أعد المحاولة.','Requests could not be loaded. Try again.'):'')+'</div>'+
 (rows.length?'<div class="svc-requests">'+rows.map(p=>'<button type="button" data-svc-position="'+esc(p.id)+'"><span class="svc-request-title"><strong dir="auto">'+esc(p.title)+'</strong><small>'+esc(p.internalCode||'')+' · '+t('إصدار ','Revision ')+esc(p.revision||1)+'</small></span><span class="ent-pill '+(p.state==='active'?'good':'')+'">'+esc(ctx.status(p.state))+'</span><span aria-hidden="true">'+t('←','→')+'</span></button>').join('')+'</div>':!data.loading&&!data.failed?'<div class="svc-empty"><span aria-hidden="true">＋</span><h3>'+t('لا توجد طلبات محفوظة بعد','No saved requests yet')+'</h3><p>'+t(ctx.canCreate?'ابدأ طلبًا جديدًا أو استورد ملف JSON سابقًا من معيار.':'ستظهر هنا الطلبات المتاحة لحسابك عند إنشائها.',ctx.canCreate?'Create a request or import an existing Miyar JSON file.':'Requests will appear here when they become available to your account.')+'</p></div>':'')+'</section>'+
 '<div class="svc-tools">'+(ctx.canCreate?'<section class="ent-card"><h2>'+t('استيراد طلب','Import a request')+'</h2><p>'+t('استعد مسودة أو حوّل قرار بحث سابق إلى طلب قابل للاستكمال.','Restore a draft or turn an earlier lookup decision into an editable request.')+'</p><label class="ent-field">'+t('ملف معيار بصيغة JSON','Miyar JSON file')+'<input id="svc-import-file" type="file" accept=".json,application/json"></label>'+button('import',t('استيراد الملف','Import file'))+'</section>':'')+'<section class="ent-card"><h2>'+t('ابحث عن مرجع مهني','Find an occupation reference')+'</h2><p>'+t('ابحث بالمسمى أو الرمز، ثم استخدم المرجع في طلبك.','Search by title or code, then use the reference in your request.')+'</p><form id="svc-search"><label class="ent-field">'+t('المسمى أو الرمز المهني','Occupation title or code')+'<input id="svc-query" type="search" placeholder="'+t('مثال: مهندس ميكانيكي أو 214401','e.g. Mechanical Engineer or 214401')+'" required maxlength="200"></label><button type="submit" class="button button-outline">'+t('بحث في الدليل','Search directory')+'</button></form></section></div>'+
 (ctx.authenticated&&ctx.canCreate&&data.localRows?.length?'<section class="ent-card"><h2>'+t('مسودات هذا الجهاز','Drafts on this device')+'</h2><p>'+t('افتح المسودة وحدد الإدارة ثم احفظها في المؤسسة. لن تُرفع أي بيانات قبل الحفظ.','Open a draft, choose a department and save it to the organization. Data is uploaded only when you save.')+'</p><div class="svc-local-drafts">'+data.localRows.map(p=>'<button type="button" class="ent-link" data-svc-local="'+esc(p.id)+'">'+esc(p.title)+' · '+t('استكمال في المؤسسة','Continue in organization')+'</button>').join('')+'</div></section>':'')+
 '<div class="svc-support"><button type="button" id="svc-help" class="ent-link">'+t('دليل الاستخدام','User guide')+'</button><button type="button" id="svc-health" class="ent-link">'+t('حالة الخدمات','Service status')+'</button></div>';
 const $=id=>target.querySelector('#svc-'+id);
 if($('new'))$('new').onclick=ctx.create;if($('resume'))$('resume').onclick=()=>ctx.open('create');
 $('register').onclick=()=>ctx.register('');if($('reviews'))$('reviews').onclick=()=>ctx.register('in_review');
 for(const id of ['account','setup'])if($(id))$(id).onclick=()=>ctx.open('connection');
 $('refresh').onclick=ctx.refresh;$('help').onclick=()=>ctx.open('tour');$('health').onclick=()=>ctx.open('readiness');
 $('search').onsubmit=e=>{e.preventDefault();ctx.search($('query').value.trim());};
 if($('import'))$('import').onclick=()=>ctx.importFile($('import-file').files[0]);
 target.querySelectorAll('[data-svc-state]').forEach(x=>x.onclick=()=>ctx.register(x.dataset.svcState));
 target.querySelectorAll('[data-svc-position]').forEach(x=>x.onclick=()=>ctx.record(x.dataset.svcPosition));
 target.querySelectorAll('[data-svc-local]').forEach(x=>x.onclick=()=>ctx.local(x.dataset.svcLocal));
}
root.MiyarService={render};
if(typeof module!=='undefined')module.exports=root.MiyarService;
})(typeof window!=='undefined'?window:globalThis);
